 ('restore_compared_footer', 'Wines, bottles, racks and wines tasted elsewhere.', 'Vins, bouteilles, casiers et vins goûtés ailleurs.'),
 ('restore_json_note', 'A JSON backup holds no photo or document files: those not on this device show as missing until a device that has them syncs.', 'Une sauvegarde JSON ne contient aucun fichier de photo ou de document : ceux qui ne sont pas sur cet appareil apparaissent comme absents jusqu’à la synchronisation avec un appareil qui les a.'),
 ('restore_files_included', 'Photos and documents included', 'Photos et documents inclus'),
 ('restore_add', 'Add what is missing', 'Ajouter ce qui manque'),
 ('restore_replace', 'Replace this cellar', 'Remplacer cette cave'),
 ('restore_footer', 'Add what is missing adds the wines, bottles, racks and Journal entries that are not in your cellar and changes nothing else. Replace this cellar makes your cellar exactly as in this backup. You can undo right after.', 'Ajouter ce qui manque ajoute les vins, bouteilles, casiers et entrées du Journal absents de votre cave, sans rien changer d’autre. Remplacer cette cave rend votre cave exactement comme dans cette sauvegarde. Vous pouvez annuler juste après.'),
 ('restore_replace_title', 'Replace this cellar?', 'Remplacer cette cave ?'),
 ('restore_replace_body', 'Your cellar becomes exactly as in this backup: what is not in it is deleted. You can undo right after.', 'Votre cave devient exactement comme dans cette sauvegarde : ce qui n’y est pas est supprimé. Vous pouvez annuler juste après.'),
 ('restore_replace_body_devices', 'Your cellar becomes exactly as in this backup, on this device and on the other devices that sync with it: what is not in it is deleted there too. You can undo right after.', 'Votre cave devient exactement comme dans cette sauvegarde, sur cet appareil et sur les autres appareils synchronisés avec lui : ce qui n’y est pas y est aussi supprimé. Vous pouvez annuler juste après.'),
 ('msg_restored', 'Cellar restored from the backup', 'Cave restaurée depuis la sauvegarde'),
 ('msg_backup_saved', 'Backup saved', 'Sauvegarde enregistrée'),
 ('err_backup_failed', 'The backup could not be made. Check that this device has enough free space, then try again.', 'La sauvegarde n’a pas pu être faite. Vérifiez qu’il reste assez d’espace libre sur cet appareil, puis réessayez.'),
 ('err_version_unreadable', 'This version could not be read.', 'Cette version n’a pas pu être lue.'),
 ("settings_export_csv", "Export a spreadsheet (CSV)", "Exporter un tableur (CSV)"),
 ("settings_export_csv_body", "One row per bottle", "Une ligne par bouteille"),
 ("settings_import", "Import a backup or a CSV file", "Importer une sauvegarde ou un fichier CSV"),
 ("settings_import_body", "A backup (ZIP or JSON) is shown first; a CSV adds what is not already in your cellar", "Une sauvegarde (ZIP ou JSON) est d’abord montrée ; un CSV ajoute ce qui n’est pas déjà dans votre cave"),
 ("settings_test_data", "Test data", "Données de test"),
 ("settings_sample_confirm_title", "Load the sample cellar?", "Charger la cave d’exemple ?"),
 ("settings_sample_confirm_body", "Sample bottles, racks and Journal entries fill your empty cellar so you can explore every screen. Erase all data removes them when you are ready to add your own.", "Des bouteilles, casiers et entrées du Journal d’exemple remplissent votre cave vide pour découvrir chaque écran. Effacer toutes les données les supprime quand vous êtes prêt à ajouter les vôtres."),
 ("settings_sample_body", "Offered while the cellar is empty and no other device syncs with this one.", "Proposée tant que la cave est vide et qu’aucun autre appareil n’est synchronisé avec celui-ci."),
 ("settings_erase", "Erase all data", "Effacer toutes les données"),
 ("settings_erase_title", "Erase all data?", "Effacer toutes les données ?"),
 ("settings_erase_body", "This erases every bottle, wine, rack and Journal entry on this device. Your settings (currency, saved searches) are kept.", "Cela efface toutes les bouteilles, tous les vins, casiers et entrées du Journal de cet appareil. Vos réglages (devise, recherches enregistrées) sont conservés."),
 ("settings_erase_body_devices", "This erases every bottle, wine, rack and Journal entry on this device and on the other devices that sync with it. Your settings (currency, saved searches) are kept.", "Cela efface toutes les bouteilles, tous les vins, casiers et entrées du Journal de cet appareil et des autres appareils synchronisés avec lui. Vos réglages (devise, recherches enregistrées) sont conservés."),
 ("settings_privacy", "Privacy", "Confidentialité"),
 ("settings_privacy_stored", "Your cellar is stored only on this device.", "Votre cave est enregistrée uniquement sur cet appareil."),
 ("settings_privacy_body", "No account, no tracking, no advertising. Devices sync directly on your network, encrypted from end to end; no server ever sees your cellar.",
  "Pas de compte, pas de pistage, pas de publicité. Les appareils se synchronisent directement sur votre réseau, chiffrés de bout en bout ; aucun serveur ne voit votre cave."),
 ("settings_privacy_stored_devices", "Your cellar is stored only on your devices.", "Votre cave est enregistrée uniquement sur vos appareils."),
 ("settings_about", "About", "À propos"),
 ("settings_beta", "Beta", "Bêta"),
 ("settings_beta_note", 'Encave is in beta: features can still change and some bugs remain. Make a backup from time to time.', 'Encave est en version bêta : les fonctionnalités peuvent encore changer et il reste des bugs. Faites une sauvegarde de temps en temps.'),
 ("help_start_beta_title", "Beta version", "Version bêta"),
 ("help_start_beta", 'Encave is in beta: features can still change and some bugs remain. Make a backup from time to time (**Settings › Your data**), and report problems on the project page.', 'Encave est en version bêta : les fonctionnalités peuvent encore changer et il reste des bugs. Faites une sauvegarde de temps en temps (**Réglages › Vos données**) et signalez les problèmes sur la page du projet.'),
