 ("msg_no_free_place", "No free place in this rack for bottles without a place.", "Aucun emplacement libre dans ce casier pour les bouteilles sans emplacement."),
 ("msg_bottles_taken_out", "Bottles taken out of their places: %1$d", "Bouteilles sorties de leur emplacement : %1$d"),
 ("msg_bottles_gone", "Bottles removed from the cellar: %1$d", "Bouteilles retirées de la cave : %1$d"),
 ("msg_wines_deleted", "Wines deleted: %1$d", "Vins supprimés : %1$d"),
 ("help_racks_several_title", "Several wines at once", "Plusieurs vins à la fois"),
 ("help_racks_several", "In the Cellar list, choose **Select wines** in the sort menu (or touch and hold a wine, then **Select**), tick the wines, then place them in a rack, take them out of their places or delete them. **Undo** puts everything back.",
  "Dans la liste de la Cave, choisissez **Sélectionner des vins** dans le menu de tri (ou maintenez un vin appuyé, puis **Sélectionner**), cochez les vins, puis rangez-les dans un casier, sortez-les de leur emplacement ou supprimez-les. **Annuler** remet tout en place."),

 # Rack check
 ("action_check_rack", "Check this rack", "Vérifier ce casier"),
 ("audit_hint", "Tap each bottle you find in the rack.", "Touchez chaque bouteille que vous trouvez dans le casier."),
 ("audit_found", "Found: %1$d of %2$d", "Trouvées : %1$d sur %2$d"),
 ("action_end_check", "End check", "Terminer la vérification"),
 ("audit_missing_title", "Bottles not found: %1$d", "Bouteilles introuvables : %1$d"),
 ("audit_missing_body", "Taken out, they stay in the cellar without a place. Gone, they leave the cellar (given away, drunk elsewhere, broken). You can undo right after.",
  "Sorties, elles restent dans la cave sans emplacement. Parties, elles quittent la cave (offertes, bues ailleurs, cassées). Vous pouvez annuler juste après."),
 ("action_take_them_out", "Take them out of the rack", "Les sortir du casier"),
 ("action_mark_them_gone", "Mark them as gone", "Les marquer comme parties"),
 ("action_keep_checking", "Keep checking", "Continuer la vérification"),
 ("audit_all_found", "Every bottle is where it should be.", "Chaque bouteille est à sa place."),
 ("audit_found_state", "Found", "Trouvée"),
 ("help_racks_check_title", "Checking a rack", "Vérifier un casier"),
 ("help_racks_check", "Choose **Check this rack**, tap each bottle you find, then **End check**. For the bottles not found, choose **Take them out of the rack** (they stay in the cellar without a place) or **Mark them as gone** (they leave the cellar). **Undo** puts everything back.",
  "Choisissez **Vérifier ce casier**, touchez chaque bouteille que vous trouvez, puis **Terminer la vérification**. Pour les bouteilles non trouvées, choisissez **Les sortir du casier** (elles restent dans la cave sans emplacement) ou **Les marquer comme parties** (elles quittent la cave). **Annuler** remet tout en place."),

 # Printed inventory and import from other apps
 ("settings_export_pdf", "Inventory for printing (PDF)", "Inventaire à imprimer (PDF)"),
 ("settings_export_pdf_body", "Every wine with its places and purchase value, for insurance or a move", "Chaque vin avec ses emplacements et sa valeur d’achat, pour l’assurance ou un déménagement"),
 ("settings_import_other", "Import from another app", "Importer depuis une autre app"),
 ("settings_import_other_body", "A CSV from CellarTracker, Vivino or a spreadsheet, read on this device", "Un CSV de CellarTracker, Vivino ou d’un tableur, lu sur cet appareil"),
 ("pdf_title", "Cellar inventory", "Inventaire de la cave"),
 ("pdf_value", "Purchase value: %1$s", "Valeur d’achat : %1$s"),
 ("pdf_wine", "Wine", "Vin"),
 ("pdf_bottles", "Bottles", "Bouteilles"),
 ("pdf_purchase_value", "Purchase value", "Valeur d’achat"),
 ("pdf_made_with", "Made with Encave", "Réalisé avec Encave"),
 ("pdf_page", "Page %1$d of %2$d", "Page %1$d sur %2$d"),
 ("msg_imported_elsewhere", "Wines tasted elsewhere imported: %1$d", "Vins goûtés ailleurs importés : %1$d"),
 ("help_data_pdf_title", "Printed inventory", "Inventaire imprimé"),
 ("help_data_pdf", "**Inventory for printing (PDF)** lists every wine with its number of bottles, places and purchase value: for your insurer, a move, or your family. The values are what you paid; Encave does not estimate market prices.",
  "**Inventaire à imprimer (PDF)** liste chaque vin avec son nombre de bouteilles, ses emplacements et sa valeur d’achat : pour votre assureur, un déménagement ou votre famille. Les valeurs sont ce que vous avez payé ; Encave n’estime pas les prix du marché."),
 ("help_data_other_title", "Coming from another app", "Venir d’une autre app"),
 ("help_data_other", "Export your cellar as CSV from CellarTracker, a spreadsheet or another app, then choose **Import from another app**. Columns are recognized by their name in English or French (wine, producer, vintage, color, quantity, location, bin, price, drinking window…). A Vivino history becomes wines tasted elsewhere in the Journal, with your ratings and notes. The file is read on this device.", "Exportez votre cave en CSV depuis CellarTracker, un tableur ou une autre app, puis choisissez **Importer depuis une autre app**. Les colonnes sont reconnues par leur nom en français ou en anglais (vin, producteur, millésime, couleur, quantité, emplacement, case, prix, fenêtre de dégustation…). Un historique Vivino devient des vins goûtés ailleurs dans le Journal, avec vos notes et commentaires. Le fichier est lu sur cet appareil."),

 # Barcodes
 ("action_scan_barcode", "Scan the barcode", "Scanner le code-barres"),
 ("barcode_hint", "Point the camera at the barcode on the bottle", "Visez le code-barres de la bouteille"),
 ("barcode_no_camera", "Allow the camera to scan the barcode, or type the digits under it.", "Autorisez l’appareil photo pour scanner le code-barres, ou saisissez les chiffres en dessous."),
 ("barcode_digits", "Barcode digits", "Chiffres du code-barres"),
 ("barcode_match_title", "Already in your cellar", "Déjà dans votre cave"),
